import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { storyBucketTokens } from "ComponentTokens.stylex";
import UIText from "UIText.react";
import UIImage from "UIImage.react";
import UIAvatar from "UIAvatar.react";
import UIIcon from "UIIcon.react";
import UIPressable from "UIPressable.react";
import LoggingSurface from "LoggingSurface.react";

const styles = stylex.create({
  tray: { display: "flex", gap: 8, marginBottom: 16, overflow: "hidden" },
  bucket: { position: "relative", flexShrink: 0, width: 112, height: 200, borderRadius: radii.xl, overflow: "hidden", display: "block", backgroundColor: storyBucketTokens.background },
  avatar: { position: "absolute", top: 12, left: 12 },
  name: { position: "absolute", left: 10, right: 10, bottom: 10, textShadow: "0 1px 2px rgba(0,0,0,0.6)" },
  create: { display: "flex", flexDirection: "column", backgroundColor: colors.cardBackground },
  plus: { position: "absolute", left: "50%", bottom: 40, transform: "translateX(-50%)", width: 40, height: 40, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", backgroundColor: colors.accent, border: `4px solid ${colors.cardBackground}` },
});

function Bucket({ bucket }) {
  const owner = bucket.owner;
  return (
    <UIPressable label={`${owner?.name}'s story`} xstyle={styles.bucket} testid="story-bucket">
      <UIImage src={bucket.preview_image?.uri} fill alt="" />
      <UIAvatar src={owner?.profile_picture?.uri} size={36} ring={!bucket.is_seen} xstyle={styles.avatar} />
      <UIText type="meta" color="onAccent" weight="semibold" numberOfLines={2} xstyle={styles.name}>
        {owner?.name}
      </UIText>
    </UIPressable>
  );
}

export default function StoriesTray({ tray }) {
  const data = useFragment(
    graphql`
      fragment StoriesTray_tray on StoriesTray {
        buckets(first: 12) {
          edges {
            node {
              id
              is_seen
              thread_count
              preview_image {
                uri
              }
              owner {
                id
                name
                profile_picture(size: 40) {
                  uri
                }
              }
            }
          }
        }
      }
    `,
    tray,
  );
  return (
    <LoggingSurface name="stories_tray">
      <div role="region" aria-label="Stories" {...stylex.props(styles.tray)}>
        <UIPressable label="Create story" xstyle={[styles.bucket, styles.create]}>
          <span {...stylex.props(styles.plus)}>
            <UIIcon name="plus" color="onAccent" />
          </span>
          <UIText type="meta" weight="semibold" xstyle={styles.name}>
            Create story
          </UIText>
        </UIPressable>
        {data.buckets?.edges.slice(0, 5).map((edge) => (
          <Bucket key={edge.node.id} bucket={edge.node} />
        ))}
      </div>
    </LoggingSurface>
  );
}
