import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { cardTokens } from "ComponentTokens.stylex";

const styles = stylex.create({
  base: { backgroundColor: colors.cardBackground, borderRadius: radii.lg, boxShadow: elevation.e1, overflow: "hidden" },
  flat: { boxShadow: "none", backgroundColor: cardTokens.background },
  padded: { padding: 12 },
});

export default function UICard({ as: Tag = "div", flat = false, padded = false, children, xstyle, ...rest }) {
  return (
    <Tag {...rest} {...stylex.props(styles.base, flat && styles.flat, padded && styles.padded, xstyle)}>
      {children}
    </Tag>
  );
}
