import * as stylex from "@stylexjs/stylex";
import { buttonTokens, buttonPrimaryTokens, buttonSecondaryTokens, buttonTertiaryTokens } from "ComponentTokens.stylex";
import { colors, spacing, radii, type } from "BaseTokens.stylex";
import UIPressable from "UIPressable.react";
import UIIcon from "UIIcon.react";
import UIText from "UIText.react";

const styles = stylex.create({
  base: {
    justifyContent: "center",
    gap: spacing.s3,
    minHeight: buttonTokens.minHeight,
    paddingInline: spacing.s6,
    borderRadius: radii.lg,
    fontWeight: type.weightSemibold,
    transitionProperty: "background-color",
    transitionDuration: buttonTokens.transitionDuration,
  },
  primary: { backgroundColor: colors.accent, color: colors.onAccent },
  secondary: { backgroundColor: buttonSecondaryTokens.background, color: colors.primaryText },
  tertiary: { backgroundColor: "transparent", color: colors.accentText },
  flat: { backgroundColor: "transparent", color: colors.secondaryText },
  large: { minHeight: 40, paddingInline: spacing.s8 },
  small: { minHeight: 28, paddingInline: spacing.s4 },
  grow: { flexGrow: 1 },
  primaryHover: { backgroundColor: { default: colors.accent, ":hover": buttonPrimaryTokens.backgroundHover } },
  tertiaryHover: { backgroundColor: { default: "transparent", ":hover": buttonTertiaryTokens.backgroundHover } },
});

export default function UIButton({ label, icon = null, use = "secondary", size = "medium", grow = false, onPress, disabled, testid, xstyle, children, ...rest }) {
  const color = use === "primary" ? "onAccent" : use === "tertiary" ? "accent" : use === "flat" ? "secondary" : "primary";
  return (
    <UIPressable
      {...rest}
      as="div"
      onPress={onPress}
      label={typeof label === "string" ? label : undefined}
      logName={typeof label === "string" ? label : "button"}
      disabled={disabled}
      testid={testid}
      xstyle={[styles.base, styles[use], size !== "medium" && styles[size], grow && styles.grow, use === "primary" && styles.primaryHover, use === "tertiary" && styles.tertiaryHover, xstyle]}
    >
      {icon !== null ? <UIIcon name={icon} size={size === "small" ? 16 : 20} color={color === "onAccent" ? "onAccent" : color === "accent" ? "accent" : "primary"} filled={icon === "like" || icon === "comment"} /> : null}
      {children ?? (label ? <UIText type={size === "small" ? "meta" : "body"} color={color} weight="semibold">{label}</UIText> : null)}
    </UIPressable>
  );
}
