import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { contactItemTokens, sponsoredUnitTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIIconButton from "UIIconButton.react";
import UIAvatar from "UIAvatar.react";
import UIImage from "UIImage.react";
import UILink from "UILink.react";
import UIPressable from "UIPressable.react";
import UIDivider from "UIDivider.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import useImpression from "useImpression";

const styles = stylex.create({
  rail: { paddingTop: 16, paddingInline: 16, paddingBottom: 24, gap: 4 },
  heading: { paddingBlock: 8 },
  sponsored: { gap: 12, padding: 8, borderRadius: sponsoredUnitTokens.radius },
  sponsoredImage: { borderRadius: 8, flexShrink: 0 },
  contact: { gap: 12, paddingInline: 8, minHeight: 44, borderRadius: contactItemTokens.radius },
  birthday: { gap: 12, padding: 8 },
});

function SponsoredUnit({ unit }) {
  const ref = useImpression(unit.id, "sponsored", unit.tracking);
  return (
    <UILink href={unit.url} block label={unit.title}>
      <div ref={ref}>
        <UIRow xstyle={styles.sponsored}>
          <UIImage src={unit.image?.uri} width={130} height={130} xstyle={styles.sponsoredImage} />
          <UIColumn gap={2}>
            <UIText weight="medium" numberOfLines={2}>
              {unit.title}
            </UIText>
            <UIText type="meta" color="secondary">
              {unit.domain}
            </UIText>
          </UIColumn>
        </UIRow>
      </div>
    </UILink>
  );
}

export default function RightRail({ rail }) {
  const data = useFragment(
    graphql`
      fragment RightRail_rail on RightRail {
        sponsored_units {
          id
          title
          domain
          url
          tracking
          image {
            uri
          }
        }
        birthdays {
          id
          name
        }
        contacts(first: 30) {
          edges {
            is_active
            node {
              id
              name
              url
              is_online
              profile_picture(size: 36) {
                uri
              }
            }
          }
        }
        group_conversations {
          id
          name
          image {
            uri
          }
        }
      }
    `,
    rail,
  );
  return (
    <LoggingSurface name="right_rail">
      <UIColumn xstyle={styles.rail}>
        <UIText type="headline4" color="secondary" xstyle={styles.heading}>
          {fbt("Sponsored", "right rail heading")}
        </UIText>
        {data.sponsored_units.map((unit) => (
          <SponsoredUnit key={unit.id} unit={unit} />
        ))}
        <UIDivider spaced />
        {data.birthdays.length ? (
          <>
            <UIText type="headline4" color="secondary" xstyle={styles.heading}>
              Birthdays
            </UIText>
            <UIRow xstyle={styles.birthday}>
              <UIIcon name="calendar" size={28} color="accent" />
              <UIText type="meta">
                <b>{data.birthdays[0].name}</b>
                {data.birthdays.length > 1 ? ` and ${data.birthdays.length - 1} others have birthdays today.` : " has a birthday today."}
              </UIText>
            </UIRow>
            <UIDivider spaced />
          </>
        ) : null}
        <UIRow justify="between">
          <UIText type="headline4" color="secondary" xstyle={styles.heading}>
            Contacts
          </UIText>
          <UIRow gap={4}>
            <UIIconButton icon="search" label="Search contacts" size={32} iconSize={16} filled={false} />
            <UIIconButton icon="more" label="Options" size={32} iconSize={16} filled={false} />
          </UIRow>
        </UIRow>
        {data.contacts?.edges.map((edge) => (
          <UIPressable key={edge.node.id} label={edge.node.name} block xstyle={styles.contact}>
            <UIAvatar src={edge.node.profile_picture?.uri} size={36} online={edge.node.is_online} />
            <UIText weight="medium" numberOfLines={1}>
              {edge.node.name}
            </UIText>
          </UIPressable>
        ))}
        <UIDivider spaced />
        <UIText type="headline4" color="secondary" xstyle={styles.heading}>
          Group conversations
        </UIText>
        {data.group_conversations.map((thread) => (
          <UIPressable key={thread.id} label={thread.name} block xstyle={styles.contact}>
            <UIAvatar src={thread.image?.uri} size={36} />
            <UIText weight="medium" numberOfLines={1}>
              {thread.name}
            </UIText>
          </UIPressable>
        ))}
      </UIColumn>
    </LoggingSurface>
  );
}
