// Loading placeholders. The shimmer animation is CSS only and isn't
// measured; the visual-completion walk treats them as loading state.
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";

const shimmer = stylex.keyframes({
  "0%": { opacity: 1 },
  "50%": { opacity: 0.5 },
  "100%": { opacity: 1 },
});

const styles = stylex.create({
  base: { backgroundColor: colors.glimmer, borderRadius: radii.sm, animationName: shimmer, animationDuration: "1.6s", animationIterationCount: "infinite" },
  size: (width, height) => ({ width, height }),
  round: { borderRadius: "50%" },
});

export default function UIGlimmer({ width = "100%", height = 12, round = false, index = 0 }) {
  return <div data-visualcompletion="loading-state" style={{ animationDelay: `${(index % 6) * 100}ms` }} {...stylex.props(styles.base, styles.size(width, height), round && styles.round)} />;
}
